# Writes core/include/dect2/results/results_fields.h: the structured-binding ladder results_io.h uses to visit the fields of a plain struct.
# Run it again (python3 tools/gen_results_fields.py) when a saved struct grows past kMaxFields fields.
import os

N = 100
here = os.path.dirname(os.path.abspath(__file__))
out = os.path.join(here, '..', 'core', 'include', 'dect2', 'results', 'results_fields.h')
lines = [
    '// Generated by tools/gen_results_fields.py: do not edit by hand.',
    '// forEachField(t, f): f(field) for every field of the plain struct t, in declaration order (results_io.h).',
    '#pragma once',
    '#include <cstddef>',
    '',
    'namespace dect2::results::detail {',
    '',
    'constexpr size_t kMaxFields = %d;' % N,
    '',
    'template <size_t n, class T, class F> void forEachFieldN(T& t, F&& f) {',
    '    if constexpr (n == 0) { (void)t; (void)f; }',
]
for n in range(1, N + 1):
    names = ', '.join('f%d' % i for i in range(n))
    calls = ' '.join('f(f%d);' % i for i in range(n))
    lines.append('    else if constexpr (n == %d) { auto& [%s] = t; %s }' % (n, names, calls))
lines += [
    '    else static_assert(n <= kMaxFields, "results: a saved struct has more fields than results_fields.h handles (run tools/gen_results_fields.py with a larger N)");',
    '}',
    '',
    '} // namespace dect2::results::detail',
    '',
]
with open(out, 'w') as f:
    f.write('\n'.join(lines))
